import { useState } from 'react';
import { JxTagInput, JxChip, JxEmptyState } from '@jinx-ui/react';

export interface ArticleTagPickerProps {
  value?: string[];
  defaultValue?: string[];
  label?: string;
  placeholder?: string;
  onChange?: (tags: string[]) => void;
}

export default function ArticleTagPicker({
  value,
  defaultValue = [],
  label = 'Теги статьи',
  placeholder = 'Введите тег и нажмите Enter',
  onChange,
}: ArticleTagPickerProps) {
  const [internalTags, setInternalTags] = useState<string[]>(defaultValue);
  const tags = value ?? internalTags;

  const commit = (next: string[]) => {
    if (value === undefined) setInternalTags(next);
    onChange?.(next);
  };

  const removeTag = (tag: string) => {
    commit(tags.filter((item) => item !== tag));
  };

  return (
    <div style={{ display: 'flex', flexDirection: 'column', gap: '12px' }}>
      <JxTagInput
        ariaLabel={label}
        placeholder={placeholder}
        value={tags}
        onValueChange={commit}
      />
      {tags.length === 0 ? (
        <JxEmptyState
          title="Тегов пока нет"
          message="Добавьте хотя бы один тег, чтобы статью было проще найти."
        />
      ) : (
        <div
          role="list"
          aria-label="Выбранные теги"
          style={{ display: 'flex', flexWrap: 'wrap', gap: '8px' }}
        >
          {tags.map((tag) => (
            <JxChip
              key={tag}
              role="listitem"
              active
              removable
              onRemove={() => removeTag(tag)}
            >
              {tag}
            </JxChip>
          ))}
        </div>
      )}
    </div>
  );
}

